import {
  DISPLAY_IDENTITY,
  displayMatrixPoint,
  displayMatrixProduct,
  displayMatrixRectangle,
  inverseDisplayMatrix,
  type DisplayMatrix,
  type DisplayRectangle,
} from './display-transform';
import { displayTwips } from './display-values';
import type { Vec } from './types';
import type { ContactMatrix } from '../assets/contact-transform';

export type DisplayGeometryContent =
  | { readonly kind: 'empty' }
  | {
      readonly kind: 'leaf';
      readonly bounds: Readonly<DisplayRectangle>;
      /** Geometry only, including the existing stage-pixel minimum for strokes. */
      readonly hit: (point: Readonly<Vec>, inverse: Readonly<ContactMatrix>) => boolean;
    }
  | { readonly kind: 'container'; readonly children: readonly DisplayGeometryNode[] };
export interface DisplayGeometryNode {
  readonly matrix: Readonly<DisplayMatrix>;
  readonly depth?: number;
  readonly clipDepth?: number;
  readonly content: DisplayGeometryContent;
}
const union = (
  a: DisplayRectangle | undefined,
  b: DisplayRectangle | undefined,
): DisplayRectangle | undefined =>
  !a
    ? b
    : !b
      ? a
      : {
          xMin: Math.min(a.xMin, b.xMin),
          xMax: Math.max(a.xMax, b.xMax),
          yMin: Math.min(a.yMin, b.yMin),
          yMax: Math.max(a.yMax, b.yMax),
        };

/** Script width: transform each declared leaf before integer-twip union.
 * Masks and masked-out children participate. Never transform a pre-unioned AABB.
 */
export function displayGeometryBounds(
  node: DisplayGeometryNode,
  parent: Readonly<DisplayMatrix> = DISPLAY_IDENTITY,
): DisplayRectangle | undefined {
  const matrix = displayMatrixProduct(parent, node.matrix),
    content = node.content;
  if (content.kind === 'empty') return undefined;
  if (content.kind === 'leaf') return displayMatrixRectangle(matrix, content.bounds);
  let bounds: DisplayRectangle | undefined;
  for (const child of content.children)
    bounds = union(bounds, displayGeometryBounds(child, matrix));
  return bounds;
}

/** Shape query: depth masks restrict ordinary children and never contribute as
 * painted content themselves. Alpha, visibility and bounds padding are absent
 * from this geometry contract. parentToStage is separate from Script width.
 */
export function displayGeometryHit(
  node: DisplayGeometryNode,
  stagePoint: Readonly<Vec>,
  parentToStage: Readonly<DisplayMatrix> = DISPLAY_IDENTITY,
): boolean {
  const point = { x: displayTwips(stagePoint.x), y: displayTwips(stagePoint.y) };
  const hit = (node: DisplayGeometryNode, parent: Readonly<DisplayMatrix>): boolean => {
    const matrix = displayMatrixProduct(parent, node.matrix),
      content = node.content;
    if (content.kind === 'empty') return false;
    if (content.kind === 'leaf') {
      const inverse = inverseDisplayMatrix(matrix);
      if (!inverse) return false;
      const local = displayMatrixPoint(inverse, point);
      return content.hit({ x: local.x / 20, y: local.y / 20 }, inverse);
    }
    const masks: DisplayGeometryNode[] = [];
    for (const child of content.children) {
      if (child.clipDepth !== undefined) {
        masks.push(child);
        continue;
      }
      if (
        masks.some(
          (mask) =>
            child.depth !== undefined &&
            mask.depth !== undefined &&
            child.depth > mask.depth &&
            child.depth <= mask.clipDepth! &&
            !hit(mask, matrix),
        )
      )
        continue;
      if (hit(child, matrix)) return true;
    }
    return false;
  };
  return hit(node, parentToStage);
}
import {
  displayGeometryBounds,
  displayGeometryHit,
  type DisplayGeometryContent,
  type DisplayGeometryNode,
} from '../core/display-geometry';
import { RetainedTransform } from '../core/retained-transform';
import { DISPLAY_IDENTITY } from '../core/display-transform';
import type { Field, Vec } from '../core/types';
import {
  readFieldPopulation,
  type ActorFieldPopulation,
  type AuthoredFieldPopulation,
  type EffectFieldPopulation,
  type FieldPopulationNode,
  type PickupFieldPopulation,
  type TutorialFieldPopulation,
} from './field-population';
import type { World } from './world';

/** Every source must supply actual geometry or an explicitly known empty clip.
 * Missing/unsupported content must throw; no circle, AABB hit or alpha fallback.
 */
export interface FieldGeometrySource {
  authored(node: AuthoredFieldPopulation): DisplayGeometryContent;
  tutorial(node: TutorialFieldPopulation): DisplayGeometryContent;
  actor(node: ActorFieldPopulation): DisplayGeometryContent;
  pickup(node: PickupFieldPopulation): DisplayGeometryContent;
  effect(node: EffectFieldPopulation): DisplayGeometryContent;
}

function compile(node: FieldPopulationNode, source: FieldGeometrySource): DisplayGeometryNode {
  if (node.kind === 'authored' || node.kind === 'tutorial')
    return {
      matrix: node.pose.matrix,
      depth: node.depth,
      clipDepth: node.clipDepth,
      content:
        node.kind === 'tutorial'
          ? source.tutorial(node)
          : node.children.length
            ? { kind: 'container', children: node.children.map((child) => compile(child, source)) }
            : source.authored(node),
    };
  const pose = new RetainedTransform(),
    transform = node.transform;
  pose.x = transform.x;
  pose.y = transform.y;
  pose.scaleX = pose.scaleY = transform.scale;
  pose.rotation = transform.rotation;
  return {
    matrix: pose.read().matrix,
    content:
      node.kind === 'actor'
        ? source.actor(node)
        : node.kind === 'pickup'
          ? source.pickup(node)
          : source.effect(node),
  };
}

/** Compile afresh at each call: source callbacks and field phases can change
 * physical children between queries. This does not install a gameplay adapter.
 */
export function readFieldGeometry(world: World, field: Field, source: FieldGeometrySource) {
  return compile(readFieldPopulation(world, field), source);
}
export function fieldScriptBounds(world: World, field: Field, source: FieldGeometrySource) {
  return displayGeometryBounds(readFieldGeometry(world, field, source));
}
export function fieldShapeHit(
  world: World,
  field: Field,
  source: FieldGeometrySource,
  stagePoint: Readonly<Vec>,
) {
  return displayGeometryHit(
    readFieldGeometry(world, field, source),
    stagePoint,
    world.fieldDisplays.readPose(field).rooted
      ? world.worldDisplays.worldMatrix(world.mainEffects.position)
      : DISPLAY_IDENTITY,
  );
}
