import {
  DISPLAY_IDENTITY,
  displayMatrixPoint,
  displayMatrixProduct,
  displayMatrixRectangle,
  inverseDisplayMatrix,
  type DisplayMatrix,
  type DisplayRectangle,
} from './display-transform';
import { displayTwips } from './display-values';
import type { Vec } from './types';
import type { ContactMatrix } from '../assets/contact-transform';

export type DisplayGeometryContent =
  | { readonly kind: 'empty' }
  | {
      readonly kind: 'leaf';
      readonly bounds: Readonly<DisplayRectangle>;
      /** Geometry only, including the existing stage-pixel minimum for strokes. */
      readonly hit: (
        point: Readonly<Vec>,
        inverse: Readonly<ContactMatrix>,
        context: Readonly<{ toStage: Readonly<DisplayMatrix>; stagePoint: Readonly<Vec> }>,
      ) => boolean;
    }
  | { readonly kind: 'container'; readonly children: readonly DisplayGeometryNode[] };
export interface DisplayGeometryNode {
  readonly matrix: Readonly<DisplayMatrix>;
  readonly depth?: number;
  readonly clipDepth?: number;
  readonly visible?: boolean;
  /** Actual maskee reference exists; this node is excluded from ordinary queries. */
  readonly isRuntimeMask?: boolean;
  /** A retained reference, even when the mask is outside this physical subtree. */
  readonly runtimeMask?: {
    readonly node: DisplayGeometryNode;
    readonly parentToStage: Readonly<DisplayMatrix>;
  };
  readonly content: DisplayGeometryContent;
}
const union = (
  a: DisplayRectangle | undefined,
  b: DisplayRectangle | undefined,
): DisplayRectangle | undefined =>
  !a
    ? b
    : !b
      ? a
      : {
          xMin: Math.min(a.xMin, b.xMin),
          xMax: Math.max(a.xMax, b.xMax),
          yMin: Math.min(a.yMin, b.yMin),
          yMax: Math.max(a.yMax, b.yMax),
        };

/** Script width: transform each declared leaf before integer-twip union.
 * Masks and masked-out children participate. Never transform a pre-unioned AABB.
 */
export function displayGeometryBounds(
  node: DisplayGeometryNode,
  parent: Readonly<DisplayMatrix> = DISPLAY_IDENTITY,
): DisplayRectangle | undefined {
  const matrix = displayMatrixProduct(parent, node.matrix),
    content = node.content;
  if (content.kind === 'empty') return undefined;
  if (content.kind === 'leaf') return displayMatrixRectangle(matrix, content.bounds);
  let bounds: DisplayRectangle | undefined;
  for (const child of content.children)
    bounds = union(bounds, displayGeometryBounds(child, matrix));
  return bounds;
}

/** Internal stage-space shape query, not the public hitTestPoint argument mapping.
 * Authored depth masks use the qualified mutable latch and exact-end admission.
 * Runtime mask references have their own parent chain and visibility policy.
 * Parent-to-stage ancestry is separate from Script width; alpha never removes geometry.
 */
export function displayGeometryHit(
  node: DisplayGeometryNode,
  stagePoint: Readonly<Vec>,
  parentToStage: Readonly<DisplayMatrix> = DISPLAY_IDENTITY,
): boolean {
  const point = { x: displayTwips(stagePoint.x), y: displayTwips(stagePoint.y) };
  return hitAtTwips(node, point, parentToStage);
}

/** Public-query boundary with an explicitly selected argument coordinate space.
 * The caller supplies player-root versus stage mapping; this traversal does not
 * guess it from a display matrix. Keep transformed twips internal, avoiding an
 * extra Number/pixel roundtrip before native shape contact.
 */
export function displayGeometryHitTestPoint(
  receiver: {
    readonly node: DisplayGeometryNode;
    readonly onStage: boolean;
    readonly parentToStage: Readonly<DisplayMatrix>;
    readonly argumentToStage: Readonly<DisplayMatrix>;
  },
  argument: Readonly<Vec>,
): boolean {
  if (!receiver.onStage) return false;
  const point = displayMatrixPoint(receiver.argumentToStage, {
    x: displayTwips(argument.x),
    y: displayTwips(argument.y),
  });
  return hitAtTwips(receiver.node, point, receiver.parentToStage);
}

function hitAtTwips(
  node: DisplayGeometryNode,
  point: Readonly<Vec>,
  parentToStage: Readonly<DisplayMatrix>,
): boolean {
  const stage = { x: point.x / 20, y: point.y / 20 };
  const hit = (
    node: DisplayGeometryNode,
    parent: Readonly<DisplayMatrix>,
    skipRuntimeMasks = true,
    skipInvisible = false,
  ): boolean => {
    if (skipRuntimeMasks && node.isRuntimeMask) return false;
    if (skipInvisible && node.visible === false && !node.isRuntimeMask) return false;
    const matrix = displayMatrixProduct(parent, node.matrix),
      content = node.content;
    const mask = node.runtimeMask;
    if (mask && !hit(mask.node, mask.parentToStage, false, false)) return false;
    if (content.kind === 'empty') return false;
    if (content.kind === 'leaf') {
      const inverse = inverseDisplayMatrix(matrix);
      if (!inverse) return false;
      const local = displayMatrixPoint(inverse, point);
      return content.hit({ x: local.x / 20, y: local.y / 20 }, inverse, {
        toStage: matrix,
        stagePoint: stage,
      });
    }
    let clippedUntil = 0;
    for (const child of content.children) {
      if (child.clipDepth !== undefined && child.clipDepth > 0) {
        clippedUntil = hit(child, matrix, true, true) ? 0 : child.clipDepth;
        continue;
      }
      // Runtime addChild entries follow authored depths, outside their ranges.
      if ((child.depth ?? Infinity) >= clippedUntil && hit(child, matrix, skipRuntimeMasks, skipInvisible))
        return true;
    }
    return false;
  };
  return hit(node, parentToStage);
}
import {
  displayGeometryBounds,
  displayGeometryHit,
  type DisplayGeometryContent,
  type DisplayGeometryNode,
} from '../core/display-geometry';
import { RetainedTransform } from '../core/retained-transform';
import type { Field, Vec } from '../core/types';
import {
  readFieldPopulation,
  type ActorFieldPopulation,
  type AuthoredFieldPopulation,
  type EffectFieldPopulation,
  type FieldPopulationNode,
  type PickupFieldPopulation,
  type TutorialFieldPopulation,
} from './field-population';
import type { World } from './world';

/** Every source must supply actual geometry or an explicitly known empty clip.
 * Missing/unsupported content must throw; no circle, AABB hit or alpha fallback.
 */
export interface FieldGeometrySource {
  authored(node: AuthoredFieldPopulation): DisplayGeometryContent;
  tutorial(node: TutorialFieldPopulation): DisplayGeometryContent;
  actor(node: ActorFieldPopulation): DisplayGeometryContent;
  pickup(node: PickupFieldPopulation): DisplayGeometryContent;
  effect(node: EffectFieldPopulation): DisplayGeometryContent;
}

function compile(node: FieldPopulationNode, source: FieldGeometrySource): DisplayGeometryNode {
  if (node.kind === 'authored' || node.kind === 'tutorial')
    return {
      matrix: node.pose.matrix,
      depth: node.depth,
      clipDepth: node.clipDepth,
      content:
        node.kind === 'tutorial'
          ? source.tutorial(node)
          : node.children.length
            ? { kind: 'container', children: node.children.map((child) => compile(child, source)) }
            : source.authored(node),
    };
  const pose = new RetainedTransform(),
    transform = node.transform;
  pose.x = transform.x;
  pose.y = transform.y;
  pose.scaleX = pose.scaleY = transform.scale;
  pose.rotation = transform.rotation;
  return {
    matrix: pose.read().matrix,
    content:
      node.kind === 'actor'
        ? source.actor(node)
        : node.kind === 'pickup'
          ? source.pickup(node)
          : source.effect(node),
  };
}

/** Compile afresh at each call: source callbacks and field phases can change
 * physical children between queries. This does not install a gameplay adapter.
 */
export function readFieldGeometry(world: World, field: Field, source: FieldGeometrySource) {
  return compile(readFieldPopulation(world, field), source);
}
export function fieldScriptBounds(world: World, field: Field, source: FieldGeometrySource) {
  return displayGeometryBounds(readFieldGeometry(world, field, source));
}
/** Internal stage-space query. Public AVM2 player-root argument mapping must be
 * bound separately before replacing source hitTestPoint gameplay calls.
 */
export function fieldStageShapeHit(
  world: World,
  field: Field,
  source: FieldGeometrySource,
  stagePoint: Readonly<Vec>,
) {
  // Qualified public shape queries require a stage-attached receiver. A detached
  // mask reference is handled separately inside the internal geometry traversal.
  if (!world.fieldDisplays.readPose(field).rooted) return false;
  return displayGeometryHit(
    readFieldGeometry(world, field, source),
    stagePoint,
    world.worldDisplays.worldMatrix(world.mainEffects.position),
  );
}

import { expect, test } from 'bun:test';
import original from './fixtures/field-mask-original.json';
import {
  displayGeometryBounds,
  displayGeometryHitTestPoint,
  type DisplayGeometryNode,
} from '../src/game/core/display-geometry';
import { DISPLAY_IDENTITY } from '../src/game/core/display-transform';

type Sample = (typeof original.samples)[number];
type Wrapper = (typeof original.wrappers)[number];
function value(sample: Sample, field: string) {
  const index = original.fields.indexOf(field),
    words = original.binaryWords[sample.wordIndices[index]],
    bytes = new DataView(new ArrayBuffer(8));
  if (index < 0 || !words) throw new Error('Missing frozen field ' + field);
  bytes.setUint32(0, words[0]);
  bytes.setUint32(4, words[1]);
  return bytes.getFloat64(0);
}
const sample = (label: string, phase: string, role: string) => {
  const found = original.samples.find((s) => s.case === label && s.phase === phase && s.role === role);
  if (!found) throw new Error(`Missing original ${label}/${phase}/${role}`);
  return found;
};

/** Control-local geometry only: independently verified original centres hit and
 * their1000px displacement misses. Reject every other Point rather than using a
 * rectangular/circular approximation of the original contours.
 */
function controlLeaf(symbol: number): DisplayGeometryNode {
  const radius = symbol === 1539 ? 8475 : symbol === 1544 ? 1010 : undefined;
  if (radius === undefined) throw new Error('Unknown control leaf ' + symbol);
  return {
    matrix: DISPLAY_IDENTITY,
    content: {
      kind: 'leaf',
      bounds: { xMin: -radius, yMin: -radius, xMax: radius, yMax: radius },
      hit: ({ x, y }) => {
        if (x === 0 && y === 0) return true;
        if (Math.abs(x) === 1000 && y === 0) return false;
        throw new Error(`Unqualified contour Point ${x}/${y}`);
      },
    },
  };
}
function authored(wrapper: Wrapper): DisplayGeometryNode {
  return {
    matrix: DISPLAY_IDENTITY,
    content: {
      kind: 'container',
      children: wrapper.children.map((child) => {
        const nested = original.wrappers.find((w) => w.id === child.symbol),
          geometry = nested ? authored(nested) : controlLeaf(child.symbol);
        return {
          ...geometry,
          matrix: { ...DISPLAY_IDENTITY, tx: child.x * 20 },
          depth: child.depth,
          clipDepth: child.clipDepth ?? undefined,
        };
      }),
    },
  };
}
const query = (node: DisplayGeometryNode, row: Sample) =>
  displayGeometryHitTestPoint({
    node, onStage: value(row, 'parentId') !== 0,
    parentToStage: DISPLAY_IDENTITY, argumentToStage: DISPLAY_IDENTITY,
  }, { x: value(row, 'point.x'), y: value(row, 'point.y') });
const dimensions = (node: DisplayGeometryNode) => {
  const b = displayGeometryBounds(node);
  return b ? [(b.xMax - b.xMin) / 20, (b.yMax - b.yMin) / 20] : [0, 0];
};

test('depth-latch traversal matches the independent original overlap/end/nested controls and declared Script bounds', () => {
  for (const wrapper of original.wrappers.filter((w) => !['runtime', 'visibility'].includes(w.label))) {
    const node = authored(wrapper),
      row = sample(wrapper.label, 'baseline', 'wrapper');
    expect(Number(query(node, row))).toBe(value(row, 'hit'));
    expect(dimensions(node)).toEqual([value(row, 'width'), value(row, 'height')]);
  }
});

test('authored visibility follows original hidden-mask versus hidden-target controls', () => {
  const wrapper = original.wrappers.find((w) => w.label === 'visibility')!;
  for (const phase of ['baseline', 'mask-hidden', 'mask-alpha0', 'target-hidden', 'target-alpha0']) {
    const node = authored(wrapper);
    if (node.content.kind !== 'container') throw new Error('Missing wrapper');
    const children = node.content.children.map((child, i) => ({
      ...child, visible: value(sample('visibility', phase, i === 0 ? 'm1' : 'target'), 'visible') === 1,
    }));
    const current = { ...node, content: { kind: 'container' as const, children } },
      row = sample('visibility', phase, 'wrapper');
    expect(Number(query(current, row))).toBe(value(row, 'hit'));
    expect(dimensions(current)).toEqual([value(row, 'width'), value(row, 'height')]);
  }
});

test('runtime reference masks reproduce every measured assignment/reparent/removal phase', () => {
  const phases = [...new Set(original.samples.filter((s) => s.case === 'runtime').map((s) => s.phase))];
  for (const phase of phases) {
    const m = sample('runtime', phase, 'm1'),
      t = sample('runtime', phase, 'target'),
      w = sample('runtime', phase, 'wrapper'),
      mask: DisplayGeometryNode = {
        ...controlLeaf(1539),
        matrix: { ...DISPLAY_IDENTITY, tx: value(m, 'x') * 20, ty: value(m, 'y') * 20 },
        visible: value(m, 'visible') === 1,
        isRuntimeMask: value(t, 'maskId') === 4,
      },
      target: DisplayGeometryNode = {
        ...controlLeaf(1544),
        matrix: { ...DISPLAY_IDENTITY, tx: value(t, 'x') * 20, ty: value(t, 'y') * 20 },
        runtimeMask: value(t, 'maskId') === 4 ? { node: mask, parentToStage: DISPLAY_IDENTITY } : undefined,
      },
      physical = [mask, target].filter((_, i) => value(i === 0 ? m : t, 'parentId') === 2),
      wrapper: DisplayGeometryNode = { matrix: DISPLAY_IDENTITY, content: { kind: 'container', children: physical } };
    for (const [node, row] of [[wrapper, w], [target, t], [mask, m]] as const) {
      expect(Number(query(node, row))).toBe(value(row, 'hit'));
      expect(dimensions(node)).toEqual([value(row, 'width'), value(row, 'height')]);
    }
    if (phase === 'different-parent') {
      const holder = sample('runtime', phase, 'holder'),
        node: DisplayGeometryNode = { matrix: DISPLAY_IDENTITY, content: { kind: 'container', children: [mask] } };
      expect(Number(query(node, holder))).toBe(value(holder, 'hit'));
      expect(dimensions(node)).toEqual([value(holder, 'width'), value(holder, 'height')]);
    }
  }
});
import { expect, test } from 'bun:test';
import {
  displayGeometryBounds,
  displayGeometryHit,
  type DisplayGeometryNode,
} from '../src/game/core/display-geometry';
import { DISPLAY_IDENTITY, type DisplayMatrix } from '../src/game/core/display-transform';
import original from './fixtures/script-bounds-original.json';

const matrix = ([a, b, c, d, tx, ty]: number[]): DisplayMatrix => ({ a, b, c, d, tx, ty });
const rectangle = (xMin: number, yMin: number, xMax: number, yMax: number): DisplayGeometryNode => ({
  matrix: DISPLAY_IDENTITY,
  content: {
    kind: 'leaf',
    bounds: { xMin, xMax, yMin, yMax },
    // Synthetic rectangular fill, not an approximation of original field art.
    hit: ({ x, y }) => x * 20 >= xMin && x * 20 <= xMax && y * 20 >= yMin && y * 20 <= yMax,
  },
});
const group = (children: DisplayGeometryNode[], transform = DISPLAY_IDENTITY): DisplayGeometryNode => ({
  matrix: transform,
  content: { kind: 'container', children },
});

test('geometry-tree Script traversal matches all independently frozen original bounds controls', () => {
  for (const control of original.cases) {
    const leaf = rectangle(-13919, -13919, 13919, 13919),
      tree = group([group([leaf], matrix(control.inner))], matrix(control.outer)),
      bounds = displayGeometryBounds(tree)!,
      [width, height] = control.trace.split(' ').slice(2, 4).map(Number);
    expect([bounds.xMax - bounds.xMin, bounds.yMax - bounds.yMin]).toEqual([
      width * 20, height * 20,
    ]);
  }
});

test('overlapping depth masks use the original mutable latch rather than conjunction', () => {
  const mask1 = { ...rectangle(0, 0, 400, 400), depth: 1, clipDepth: 6 },
    mask2 = { ...rectangle(200, 0, 600, 400), depth: 2, clipDepth: 6 },
    target = { ...rectangle(0, 0, 1000, 1000), depth: 4 },
    tree = group([mask1, mask2, target]);
  expect(displayGeometryHit(tree, { x: 5, y: 5 })).toBe(false);
  expect(displayGeometryHit(tree, { x: 15, y: 5 })).toBe(true);
  expect(displayGeometryHit(tree, { x: 25, y: 5 })).toBe(true);
  // A later mask hit resets a preceding miss; exact end depth is admitted.
  expect(displayGeometryHit(group([mask1, { ...target, depth: 6 }]), { x: 25, y: 5 })).toBe(true);
  expect(displayGeometryHit(group([mask1, mask2]), { x: 15, y: 5 })).toBe(false);
  // Masks and the fully unclipped target still contribute to Script width.
  expect(displayGeometryBounds(tree)).toEqual({ xMin: 0, xMax: 1000, yMin: 0, yMax: 1000 });
});

test('runtime children beyond mask depths and nested children inherit the correct mask scope', () => {
  const mask = { ...rectangle(0, 0, 200, 200), depth: 1, clipDepth: 4 },
    target = rectangle(400, 0, 600, 200),
    masked = { ...group([target]), depth: 2 };
  expect(displayGeometryHit(group([mask, masked]), { x: 25, y: 5 })).toBe(false);
  expect(displayGeometryHit(group([mask, { ...masked, depth: 5 }]), { x: 25, y: 5 })).toBe(true);
  expect(displayGeometryHit(group([mask, target]), { x: 25, y: 5 })).toBe(true);
});

test('parent-to-stage Points affect shape contact but never leak into the clip Script bounds', () => {
  const leaf = rectangle(0, 0, 200, 200),
    tree = group([leaf], { ...DISPLAY_IDENTITY, tx: 201, ty: -101 }),
    parent = { ...DISPLAY_IDENTITY, a: 0.5, d: 0.5, tx: 5500, ty: 4500 };
  expect(displayGeometryHit(tree, { x: 282, y: 225 }, parent)).toBe(true);
  expect(displayGeometryHit(tree, { x: 282, y: 225 })).toBe(false);
  expect(displayGeometryHit(tree, { x: 12, y: -3 })).toBe(true);
  expect(displayGeometryBounds(tree)).toEqual({ xMin: 201, xMax: 401, yMin: -101, yMax: 99 });
});

test('leaf contact receives actual stage-to-leaf scale for minimum stroke width', () => {
  const seen: unknown[] = [],
    leaf: DisplayGeometryNode = {
      matrix: { ...DISPLAY_IDENTITY, a: 0.5, d: 0.25 },
      content: {
        kind: 'leaf', bounds: { xMin: -20, yMin: -20, xMax: 20, yMax: 20 },
        hit: (point, inverse) => { seen.push({ point, inverse }); return true; },
      },
    };
  expect(displayGeometryHit(leaf, { x: 0.5, y: 0.5 })).toBe(true);
  expect(seen).toEqual([{ point: { x: 1, y: 2 }, inverse: { a: 2, b: -0, c: -0, d: 4, tx: -0, ty: 0 } }]);
});

test('empty geometry stays distinct from a zero-scaled nonempty leaf', () => {
  expect(displayGeometryBounds({ matrix: DISPLAY_IDENTITY, content: { kind: 'empty' } })).toBeUndefined();
  const leaf = { ...rectangle(-20, -20, 20, 20), matrix: { ...DISPLAY_IDENTITY, a: 0, d: 0 } };
  expect(displayGeometryBounds(leaf)).toEqual({ xMin: 0, xMax: 0, yMin: 0, yMax: 0 });
});

test('authored hidden masks block while hidden ordinary targets keep geometry', () => {
  const mask = { ...rectangle(0, 0, 200, 200), depth: 1, clipDepth: 4, visible: false },
    target = { ...rectangle(0, 0, 200, 200), depth: 2, visible: false };
  expect(displayGeometryHit(group([mask, target]), { x: 5, y: 5 })).toBe(false);
  expect(displayGeometryHit(group([{ ...mask, visible: true }, target]), { x: 5, y: 5 })).toBe(true);
  expect(displayGeometryHit(mask, { x: 5, y: 5 })).toBe(true);
});

test('runtime masks stay geometric references across separate parents and are excluded as ordinary content', () => {
  const mask = { ...rectangle(0, 0, 200, 200), isRuntimeMask: true, visible: false },
    target = { ...rectangle(0, 0, 1000, 1000), runtimeMask: { node: mask, parentToStage: DISPLAY_IDENTITY } };
  expect(displayGeometryHit(mask, { x: 5, y: 5 })).toBe(false);
  expect(displayGeometryHit(target, { x: 5, y: 5 })).toBe(true);
  expect(displayGeometryHit(target, { x: 25, y: 5 })).toBe(false);
  const shifted = { ...target, runtimeMask: { node: mask, parentToStage: { ...DISPLAY_IDENTITY, tx: 400 } } };
  expect(displayGeometryHit(shifted, { x: 5, y: 5 })).toBe(false);
  expect(displayGeometryHit(shifted, { x: 25, y: 5 })).toBe(true);
  // Mask references do not invent physical bounds at the target's parent.
  expect(displayGeometryBounds(shifted)).toEqual({ xMin: 0, yMin: 0, xMax: 1000, yMax: 1000 });
  expect(displayGeometryBounds(group([mask]))).toEqual({ xMin: 0, yMin: 0, xMax: 200, yMax: 200 });
});
